() => {
  // Look for links to AirPods 3rd generation
  const links = Array.from(document.querySelectorAll('a'));
  const airpods3Links = links.filter(a => {
    const href = a.getAttribute('href') || '';
    const ariaLabel = a.getAttribute('aria-label') || '';
    const text = a.textContent || '';
    return href.includes('airpods-3') || ariaLabel.toLowerCase().includes('airpods 3') || ariaLabel.toLowerCase().includes('airpods (3') || text.includes('AirPods (3rd');
  });
  return airpods3Links.map(a => ({
    href: a.getAttribute('href'),
    ariaLabel: a.getAttribute('aria-label'),
    text: a.textContent.trim().slice(0, 100)
  }));
}

() => {
  // Look for pricing information for AirPods 3rd gen
  const priceElements = document.querySelectorAll('.typography-body-reduced, [data-pricing-info], [class*="price"]');
  const results = [];

  // Get all text nodes containing dollar signs
  const allElements = document.querySelectorAll('div, span, p');
  allElements.forEach(el => {
    const text = el.textContent.trim();
    if ((text.match(/^\$\d/) || text.includes('$129') || text.includes('$169') || text.includes('$199')) && !el.children.length) {
      results.push({
        text: text,
        path: el.className
      });
    }
  });

  return {
    visiblePrices: results.slice(0, 20),
    comparisonOptions: Array.from(document.querySelectorAll('option')).filter(o => o.textContent.includes('3rd generation')).map(o => o.textContent)
  };
}

() => {
  // Dismiss any modal/overlay
  const closeButtons = document.querySelectorAll('button[aria-label*="close"], button[class*="close"], .modal-close, [class*="modal"] [aria-label*="Close"]');
  closeButtons.forEach(btn => btn.click());

  // Try to find any "continue" buttons
  const continueButtons = document.querySelectorAll('button');
  continueButtons.forEach(btn => {
    const text = btn.textContent.toLowerCase();
    if (text.includes('continue') || text.includes('accept') || text.includes('got it')) {
      btn.click();
    }
  });

  return {
    closedButtons: closeButtons.length,
    url: window.location.href,
    title: document.title
  };
}

() => {
  // Find all price-related text on the page
  const results = [];
  document.querySelectorAll('div, span, p').forEach(el => {
    const text = el.textContent.trim();
    if ((text.match(/^\$\d/) || text.match(/^—$/)) && !el.querySelector('*') && text.length < 30) {
      // Get context by looking at the parent section
      let parent = el;
      for (let i = 0; i < 3; i++) {
        if (parent.parentElement) parent = parent.parentElement;
      }
      results.push({
        text: text,
        section: parent.className || 'no-class'
      });
    }
  });
  return results.slice(0, 30);
}
